    value: string;
    kind: RecipeFixedValueKind;
    // SET ONLY ON A LOOKUP'S Id WRITTEN BY "Use existing <Parent> from org…" (#421)
    orgRecord?: { orgLabel: string; parentObjectApiName: string };
